+      function save() {
+        try {
+          localStorage.setItem(storageKey, JSON.stringify(todos));
+          warning.hidden = true;
+        } catch (error) {
+          storageError("Your changes could not be saved. Keep this page open to avoid losing them.", error);
+        }
+      }
+
+      function render() {
+        const active = todos.filter(todo => !todo.completed).length;
+        const visible = todos.filter(todo =>
+          filter === "all" || (filter === "completed" ? todo.completed : !todo.completed)
+        );
+        const fragment = document.createDocumentFragment();
+
+        for (const todo of visible) {
+          const row = document.createElement("li");
+          row.className = todo.completed ? "todo completed" : "todo";
+          row.dataset.id = String(todo.id);
+
+          const checkbox = document.createElement("input");
+          checkbox.type = "checkbox";
+          checkbox.className = "todo-check";
+          checkbox.id = `todo-${todo.id}`;
+          checkbox.checked = todo.completed;
+
+          const label = document.createElement("label");
+          label.className = "todo-text";
+          label.htmlFor = checkbox.id;
+          label.textContent = todo.text;
+
+          const remove = document.createElement("button");
+          remove.type = "button";
+          remove.className = "delete";
+          remove.textContent = "×";
+          remove.setAttribute("aria-label", `Delete ${todo.text}`);
+
+          row.append(checkbox, label, remove);
+          fragment.append(row);
+        }
+
+        list.replaceChildren(fragment);
+        const count = document.querySelector("#count");
+        const number = document.createElement("strong");
+        number.textContent = String(active);
+        count.replaceChildren(number, ` ${active === 1 ? "item" : "items"} left`);
+        toggleAll.disabled = todos.length === 0;
+        toggleAll.checked = todos.length > 0 && active === 0;
+        toggleAll.indeterminate = active > 0 && active < todos.length;
+        clearCompleted.disabled = active === todos.length;
+        filters.forEach(button => button.setAttribute("aria-pressed", String(button.dataset.filter === filter)));
+
+        document.querySelector("#empty").hidden = visible.length > 0;
+        const emptyCopy = filter === "completed"
+          ? ["Nothing completed just yet.", "Every small step counts. Check off a task when you're ready."]
+          : filter === "active" && todos.length > 0
+            ? ["All caught up.", "Take a breath. You've earned a little space."]
+            : filter === "active"
+              ? ["No active tasks.", "Add a task above whenever you're ready."]
+              : ["A fresh start.", "Add your first task and make room for what matters."];
+        document.querySelector("#empty-title").textContent = emptyCopy[0];
+        document.querySelector("#empty-description").textContent = emptyCopy[1];
+      }
+
+      function commit(message) {
+        save();
+        render();
+        announcement.textContent = message;
+      }
+
+      function restoreRowFocus(id, selector, previousIndex) {
+        const rows = [...list.children];
+        const row = rows.find(item => item.dataset.id === id) ||
+          rows[Math.min(previousIndex, rows.length - 1)];
+        if (row) row.querySelector(selector).focus();
+        else input.focus();
+      }
+
+      form.addEventListener("submit", event => {
+        event.preventDefault();
+        const text = input.value.trim();
+        if (!text) {
+          input.setCustomValidity("Please enter a task.");
+          input.reportValidity();
+          return;
+        }
+        todos.push({ id: nextId++, text, completed: false });
+        input.value = "";
+        // Reveal newly added tasks even when viewing completed tasks.
+        if (filter === "completed") filter = "all";
+        commit("Task added.");
+        input.focus();
+      });
+      input.addEventListener("input", () => input.setCustomValidity(""));
+
+      list.addEventListener("change", event => {
+        if (!event.target.matches(".todo-check")) return;
+        const row = event.target.closest(".todo");
+        const index = [...list.children].indexOf(row);
+        const todo = todos.find(item => String(item.id) === row.dataset.id);
+        todo.completed = event.target.checked;
+        commit(todo.completed ? "Task completed." : "Task marked active.");
+        restoreRowFocus(row.dataset.id, ".todo-check", index);
+      });
+
+      list.addEventListener("click", event => {
+        const button = event.target.closest(".delete");
+        if (!button) return;
+        const row = button.closest(".todo");
+        const index = [...list.children].indexOf(row);
+        todos = todos.filter(todo => String(todo.id) !== row.dataset.id);
+        commit("Task deleted.");
+        restoreRowFocus(row.dataset.id, ".delete", index);
+      });
+
+      toggleAll.addEventListener("change", () => {
+        const completed = toggleAll.checked;
+        todos.forEach(todo => { todo.completed = completed; });
+        commit(completed ? "All tasks completed." : "All tasks marked active.");
+      });
+
+      clearCompleted.addEventListener("click", () => {
+        todos = todos.filter(todo => !todo.completed);
+        commit("Completed tasks cleared.");
+        input.focus();
+      });
+
+      filters.forEach(button => button.addEventListener("click", () => {
+        filter = button.dataset.filter;
+        render();
+      }));
+
+      render();
+    })();
+  </script>
+</body>
+</html>
*** End Patch

